mapper.update:
UPDATE gateway_mcp_task_instance SET deleted_at = (CURRENT_TIMESTAMP AT TIME ZONE 'UTC'), version = version + 1,
    update_user_id = #{et.updateUserId}, update_time = #{et.updateTime,jdbcType=TIMESTAMP}
WHERE id = #{et.id} AND tenant_id = #{et.tenantId} AND deleted_at IS NULL AND version = #{MP_OPTLOCK_VERSION_ORIGINAL}

UPDATE gateway_mcp_task_instance SET state = #{et.state},
    input_payload = #{et.inputPayload,typeHandler=top.egon.cola.component.yuheng.mcp.engine.mcp.dao.typehandler.McpJsonbTypeHandler,jdbcType=OTHER},
    result_payload = #{et.resultPayload,typeHandler=top.egon.cola.component.yuheng.mcp.engine.mcp.dao.typehandler.McpJsonbTypeHandler,jdbcType=OTHER},
    error_payload = #{et.errorPayload,typeHandler=top.egon.cola.component.yuheng.mcp.engine.mcp.dao.typehandler.McpJsonbTypeHandler,jdbcType=OTHER},
    worker_owner = NULL, lease_until = NULL, revision = #{et.revision}, version = version + 1,
    update_user_id = #{et.updateUserId}, update_time = #{et.updateTime,jdbcType=TIMESTAMP}
WHERE id = #{et.id} AND tenant_id = #{et.tenantId} AND deleted_at IS NULL AND version = #{et.version}
    AND state = #{expectedState} AND revision = #{expectedRevision}
    AND ((#{expectedWorkerOwnerNull} = TRUE AND worker_owner IS NULL)
        OR (#{expectedWorkerOwnerNull} = FALSE AND worker_owner = #{expectedWorkerOwner,jdbcType=VARCHAR}))

UPDATE gateway_mcp_task_instance SET state = #{et.state}, worker_owner = NULL, lease_until = NULL,
    revision = #{et.revision}, version = version + 1,
    update_user_id = #{et.updateUserId}, update_time = #{et.updateTime,jdbcType=TIMESTAMP}
WHERE id = #{et.id} AND tenant_id = #{et.tenantId} AND deleted_at IS NULL AND version = #{et.version}
    AND state = #{expectedState} AND revision = #{expectedRevision}
